  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Expands water filling to the specified distance from the source using BFS.
   * Algorithm: 
   *   1. If distance == 0, do nothing.
   *   2. Use BFS starting from all currently filled tiles (or from source if first time).
   *   3. For each tile at current distance, check all 4 directions:
   *      a. Get neighboring cell.
   *      b. If neighbor is FillableCell with a pipe:
   *         - Check if current cell's outgoing direction connects to neighbor's incoming direction (opposite direction).
   *         - If connected and neighbor pipe not filled, mark it as filled.
   *   4. Update prevFilledDistance and prevFilledTiles.
   * Related Features: filledTiles, sourceCell, sinkCell, prevFilledDistance, prevFilledTiles
   * Related Classes: Coordinate, FillableCell, Pipe, Direction, TerminationCell
   * Input: distance : int - the current water expansion distance.
   * Output: void
   * Pre-condition: distance >= 0
   * Post-condition: All reachable pipes within the given distance from source are marked as filled if connections allow.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated
   */
  public void fillTiles(final int distance)
  {
    if (distance == 0)
    {
      return;
    }
    if (distance == 1)
    {
      fillBeginTile();
    }
    int newlyFilled = 0;
    for (int r = 0; r < rows; r++)
    {
      for (int c = 0; c < cols; c++)
      {
        Cell curCell = cell[r][c];
        if (curCell instanceof FillableCell)
        {
          FillableCell fc = (FillableCell) curCell;
          if (fc.getPipe() != null && !fc.getPipe().isFilled())
          {
            Coordinate curCoord = new Coordinate();
            curCoord.setRow(r);
            curCoord.setCol(c);
            boolean hasFilledNeighbor = false;
            for (Direction dir : fc.getPipe().getConnections())
            {
              int nr = r;
              int nc = c;
              switch (dir)
              {
                case UP: nr = r - 1; break;
                case DOWN: nr = r + 1; break;
                case LEFT: nc = c - 1; break;
                case RIGHT: nc = c + 1; break;
              }
              if (nr >= 0 && nr < rows && nc >= 0 && nc < cols)
              {
                Cell neighborCell = cell[nr][nc];
                if (neighborCell instanceof FillableCell)
                {
                  FillableCell neighborFc = (FillableCell) neighborCell;
                  if (neighborFc.getPipe() != null && neighborFc.getPipe().isFilled())
                  {
                    for (Direction neighborDir : neighborFc.getPipe().getConnections())
                    {
                      if (neighborDir.equals(Direction.UP) && dir.equals(Direction.DOWN)) hasFilledNeighbor = true;
                      else if (neighborDir.equals(Direction.DOWN) && dir.equals(Direction.UP)) hasFilledNeighbor = true;
                      else if (neighborDir.equals(Direction.LEFT) && dir.equals(Direction.RIGHT)) hasFilledNeighbor = true;
                      else if (neighborDir.equals(Direction.RIGHT) && dir.equals(Direction.LEFT)) hasFilledNeighbor = true;
                    }
                  }
                }
                if (neighborCell instanceof TerminationCell)
                {
                  if (((TerminationCell) neighborCell).isFilled())
                  {
                    hasFilledNeighbor = true;
                  }
                }
              }
            }
            if (hasFilledNeighbor)
            {
              fc.getPipe().setFilled(true);
              getFilledTiles().add(curCoord);
              newlyFilled++;
            }
          }
        }
      }
    }
    prevFilledTiles = newlyFilled;
  }

